CREATE TABLE "ExternalWorkFeeds" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Key" varchar(200) NOT NULL UNIQUE,
    "Namespace" varchar(16) NOT NULL,
    "MediaTypeId" smallint NOT NULL REFERENCES "MediaTypes" ("Id"),
    "MediaSubtypeId" smallint NULL REFERENCES "MediaSubtypes" ("Id"),
    "DiscoverFeedTypeId" smallint NULL CHECK ("DiscoverFeedTypeId" BETWEEN 1 AND 4),
    "Page" integer NOT NULL CHECK ("Page" BETWEEN 1 AND 500),
    "SourceValue" varchar(64) NULL,
    "Language" varchar(35) NULL,
    "RefreshedAt" timestamptz NULL,
    "RetryAfter" timestamptz NOT NULL DEFAULT statement_timestamp(),
    UNIQUE NULLS NOT DISTINCT ("Namespace", "MediaTypeId", "MediaSubtypeId", "DiscoverFeedTypeId", "Page", "SourceValue", "Language"),
    CHECK (("SourceValue" IS NULL) <> ("DiscoverFeedTypeId" IS NULL)),
    CHECK ("SourceValue" IS NULL OR "Page" = 1)
);
CREATE INDEX "IX_ExternalWorkFeeds_Retry" ON "ExternalWorkFeeds" ("RetryAfter", "Id");

CREATE TABLE "ExternalWorkFeedItems" (
    "FeedId" bigint NOT NULL REFERENCES "ExternalWorkFeeds" ("Id") ON DELETE CASCADE,
    "Position" integer NOT NULL CHECK ("Position" BETWEEN 1 AND 500),
    "ExternalWorkId" bigint NOT NULL REFERENCES "ExternalWorks" ("Id") ON DELETE CASCADE,
    PRIMARY KEY ("FeedId", "Position"),
    UNIQUE ("FeedId", "ExternalWorkId")
);
CREATE INDEX "IX_ExternalWorkFeedItems_Work" ON "ExternalWorkFeedItems" ("ExternalWorkId");
